/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDCOM00007_FUND.xml";
scwin.gJongcode = ""; //업종코드
scwin.gUpjongJongmok = ""; //업종에 따른 종목
scwin.gFilterType = ""; //"S":종목검색버튼,"O"
scwin.gJongName = ""; //종목명
scwin.ssMarket = "N"; //종목콤보확인

scwin.stat = ""; //상장구분
scwin.gSecu = ""; //증권구분
scwin.gListStatCd = "";
scwin.tpcd = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //세션의 시장구분 

scwin.fn_list_sync = function() {
    scwin.gSecu = scwin.fn_setSecu(scwin.gSecu);
    var url = "/isurcd.do?method=searchIsurCdFund&inputMessageId=ISUR_CD_FUND&outputMessageId=ISUR_CD_FUND" + "&LIST_STAT_CD=" + scwin.stat + "&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.tpcd + "&SECUGRP_ID=" + scwin.gSecu + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_jongmok.DataID = encodeURI(url);
    dts_jongmok.reset();
    $c.cm.ShowWin(grd_jongmok);
};


/********************************************** 
 * 함수명   : Jongmok()
 * 설명       : 가나다라..검색
 ***********************************************/
scwin.Jongmok = function(prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";
    dts_jongmok.UseFilter = "true";
    dts_jongmok.Filter();
    grd_jongmok.Redraw = "false";
    dts_jongmok.sort("+COM_ABBRV", 0);
    //dts_jongmok.sort(); // W-Craft 주석처리 
    var cnt = 0;
    for (i = 1; i <= dts_jongmok.getTotalRow(); i++) {
        var name = dts_jongmok.getCellData(i, "COM_ABBRV").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.setRowPosition(cnt + 11, 0);
    dts_jongmok.setRowPosition(cnt, 0);
    grd_jongmok.focus();
};


/********************************************** 
 * 함수명   : JongmokName()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokName = function(keyCode) {
    //if(keyCode==13) on_close();
    grd_jongmok.Redraw = "false";
    dts_jongmok.sort("+COM_ABBRV", 0);
    //dts_jongmok.sort(); // W-Craft 주석처리 
    var cnt = 0;
    var len = txb_jongmokName.getValue().length;
    var txtVal = txb_jongmokName.getValue().toUpperCase();
    for (i = 1; i <= dts_jongmok.getTotalRow(); i++) {
        var name = dts_jongmok.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
        if (txtVal == name) {
            cnt = i;
            break;
        }
    }
    if (cnt == 0) {
        dts_jongmok.sort("+COM_NM", 0);
        //dts_jongmok.sort(); // W-Craft 주석처리 
        for (i = 1; i <= dts_jongmok.getTotalRow(); i++) {
            var name = dts_jongmok.getCellData(i, "COM_NM").substring(0, len).toUpperCase();
            if (txtVal == name) {
                cnt = i;
                break;
            }
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.setRowPosition(cnt + 11, 0);
    dts_jongmok.setRowPosition(cnt, 0);
};

/********************************************** 
 * 함수명   : JongmokSearch()
 * 설명       : 종목명검색
 ***********************************************/
scwin.skw = "";
scwin.JongmokSearch = function() {
    scwin.skw = (txb_jongmokName.getValue()).toUpperCase();
    dts_jongmok.UseFilter = "true";
    dts_jongmok.Filter();
    dts_jongmok.setRowPosition(1, 0);
};


/********************************************** 
 * 함수명   : Confirm()
 * 설명       : 부모창으로 종목코드 전달
 ***********************************************/
scwin.Confirm = async function() {
    //frame.Provider("../").종목코드id
    var pJongCode = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "ISUR_CD");
    var pJongNm = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "COM_ABBRV");
    var ld_mkt_tp_cd = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD");
    $c.frame.path("../").isurSearch_Rtn(pJongCode, pJongNm, ld_mkt_tp_cd);
    await $c.frame.CloseFrame();
};
scwin.fn_code1_sync = function() {
    var url1 = "/tbmccdval.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ENG_NM=SPOT_ISU_TRD_MKT_TP_CD";
    MxDataSet_code1.DataID = encodeURI(url1);
    MxDataSet_code1.reset();
    var url2 = "/tbmccdval.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ENG_NM=LIST_STAT_CD";
    MxDataSet_code2.DataID = encodeURI(url2);
    MxDataSet_code2.reset();
};
scwin.marketSetCombo = function() {
    var cIndex;
    var name;
    if (scwin.tpcd != "") {
        for (i = 1; i <= MxDataSet_code1.getTotalRow(); i++) {
            name = MxDataSet_code1.getCellData(i, "CD_VAL");
            if (name == scwin.tpcd) {
                cIndex = i - 1;
                break;
            }
        }
        //사용자의 시장구분값이 없을 시 '조건없음' 으로 초기화
        if (scwin.tpcd != "1" && scwin.tpcd != "2" && scwin.tpcd != "6") {
            combo_market.setSelectedIndex(0);
            txb_jongmokName.setValue("");
            scwin.skw = "";
            scwin.tpcd = MxDataSet_code1.getCellData(combo_market.getSelectedIndex() + 1, "CD_VAL");
            scwin.fn_list_sync();
        } else {
            combo_market.setSelectedIndex(cIndex);
        }
    }
    if (scwin.tpcd == "1" || scwin.tpcd == "2" || scwin.tpcd == "6") {
        combo_market.setDisabled(true);
    }
    scwin.ssMarket = "Y";

    //상장구분을 "상장"으로 초기화
    combo_stat.setSelectedIndex(1);
};


/********************************************** 
 * 함수명   : fn_setSecu(value)
 * 설명       :  검색하고자 하는 증권회사 셋팅
 ***********************************************/
scwin.fn_setSecu = function(secu) {
    if (secu == "0" || secu == "") {
        secu = "RT,SC,MF";
    }
    return secu;
};
scwin.dts_jongmok_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_jongmok);
};
scwin.MxDataSet_code1_OnLoadCompleted = function(rowcount) {
    scwin.marketSetCombo();
};
scwin.MxDataSet_code1_OnFilter = function(row) {
    if (dts_jongmok.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD") == scwin.gJongcode) return true;

    else return false;
};
scwin.grd_jongmok_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        scwin.Confirm();
    }
};
scwin.grd_jongmok_OnDblClick = function(row, colid) {
    scwin.Confirm();
};
scwin.img_search_onclick = function() {
    scwin.JongmokName(txb_jongmokName.getValue());
};
scwin.txb_jongmokName_onkeydown = function() {
    if (window.event.keyCode == "13") {
        //JongmokName(window.event.keyCode);
        $c.stockSearch.JongmokSearch();
    }
};
scwin.combo_market_OnSelChange = function() {
    if (scwin.ssMarket == "Y") {
        txb_jongmokName.setValue("");
        scwin.skw = "";
        scwin.tpcd = MxDataSet_code1.getCellData(combo_market.getSelectedIndex() + 1, "CD_VAL");
        scwin.fn_list_sync();
    }
};
scwin.combo_stat_OnSelChange = function() {
    txb_jongmokName.setValue("");
    scwin.skw = "";
    scwin.stat = $c.cp.valueOfIndex(combo_stat, "Column2", combo_stat.getSelectedIndex());
    if (scwin.stat == '0') {
        scwin.stat = "";
    }
    scwin.fn_list_sync();
};
scwin.combo_Secu_OnSelChange = function() {
    //2015.10.14_증권구분추가_이민철
    //회사명 초기화
    txb_jongmokName.setValue("");
    //회사명 UPPERCASE
    scwin.skw = "";
    //증권구분 value
    scwin.gSecu = $c.cp.valueOfIndex(combo_Secu, "Column2", combo_Secu.getSelectedIndex());

    //증권구분 셋팅("", 0 일때 값 셋팅)
    scwin.gSecu = scwin.fn_setSecu(scwin.gSecu);

    //종목조회
    scwin.fn_list_sync();
};
scwin.dts_jongmok_OnFilter = function(row) {
    if (scwin.skw != "") {
        f1 = (dts_jongmok.getCellData(row, "COM_ABBRV")).toUpperCase();
        f2 = (dts_jongmok.getCellData(row, "OLD_COM_ABBRV")).toUpperCase();
        f3 = (dts_jongmok.getCellData(row, "COM_NM")).toUpperCase();
        if (f1.indexOf(scwin.skw) != -1) {
            return true;
        } else if (f2.indexOf(scwin.skw) != -1) {
            return true;
        } else if (f3.indexOf(scwin.skw) != -1) {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
};
scwin.btn_ga_onclick = function() {
    scwin.Jongmok('가', '나');
