scwin.gform_onload = function() {
    scwin.stat = $c.frame.path("../").js_listStatCd;
    //상장상태여부

    if (scwin.stat == undefined) {
        scwin.stat = "";
    } else {
        scwin.gListStatCd = scwin.stat;
        if (scwin.gListStatCd == "Y") {
            combo_stat.bindColVal = 'Y';
            combo_stat.setDisabled(true);
        }
    }
    $c.cm.PanelToGroupBox_01(panel_1);
    $c.cm.PanelToGroupBox_02(panel_2);
    dts_jongmok.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=isurcd";
    dts_jongmok.reset();
    MxDataSet_code1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";
    MxDataSet_code1.reset();
    MxDataSet_code2.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";
    MxDataSet_code2.reset();
    scwin.fn_code1_sync();
    scwin.fn_list_sync();
};
